import base64
import json
from pathlib import Path
from datetime import datetime, timezone

NEWS = Path('news.json')

KIRKUK_TITLE = 'مجلس محافظة كركوك يعقد جلسته الـ25 بحضور 15 عضواً لمناقشة عدد من الملفات بينها استضافة مديري شرطة المحافظة والبلدية'
KIRKUK_IMAGE = './assets/editorial/kirkuk-council-25-2026-09-08.jpg'
KIRKUK_URL = 'https://altaasahnews2026.github.io/altaasah-news/editorial/kirkuk-council-25-2026-09-08'
KIRKUK_PUBLISHED = '2026-09-08T13:11:00+03:00'

BILAL_TITLE = 'تداول أنباء عن اعتقال مالك قناة عراق الحدث بلال المالكي على خلفية قضية قصي شفيق'
BILAL_IMAGE = './assets/editorial/bilal-al-maliki-2026-09-08.jpg'
BILAL_URL = 'https://altaasahnews2026.github.io/altaasah-news/editorial/bilal-al-maliki-2026-09-08'
BILAL_PUBLISHED = '2026-09-08T14:17:00+03:00'

BILAL_IMAGE_B64 = ''''''


def ensure_bilal_image():
    path = Path(BILAL_IMAGE.lstrip('./'))
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists() or path.stat().st_size < 1000:
        raw = BILAL_IMAGE_B64 + ('=' * (-len(BILAL_IMAGE_B64) % 4))
        path.write_bytes(base64.b64decode(raw))


def main():
    ensure_bilal_image()
    data = json.loads(NEWS.read_text(encoding='utf-8'))
    items = data.get('items', [])
    items = [x for x in items if x.get('title') not in {KIRKUK_TITLE, BILAL_TITLE}]

    kirkuk = {
        'title': KIRKUK_TITLE,
        'url': KIRKUK_URL,
        'image': KIRKUK_IMAGE,
        'original_image': KIRKUK_IMAGE,
        'published': KIRKUK_PUBLISHED,
        'category': 'كركوك',
        'region': 'كركوك',
        'kirkuk': True,
        'breaking': False,
        'source_name': 'التاسعة نيوز',
        'summary': 'يعقد مجلس محافظة كركوك جلسته الـ25 بحضور 15 عضواً لمناقشة عدد من الملفات، بينها استضافة مديري شرطة المحافظة والبلدية لبحث الملفات المطروحة على جدول أعمال المجلس.'
    }

    bilal = {
        'title': BILAL_TITLE,
        'url': BILAL_URL,
        'image': BILAL_IMAGE,
        'original_image': BILAL_IMAGE,
        'published': BILAL_PUBLISHED,
        'category': 'أمن',
        'region': 'العراق',
        'kirkuk': False,
        'breaking': True,
        'source_name': 'التاسعة نيوز',
        'summary': 'تداولت مصادر ومنصات إعلامية عراقية أنباءً بشأن مالك قناة «عراق الحدث» بلال المالكي، على خلفية التحقيقات والاعترافات المنسوبة إلى الصحفي المعتقل قصي شفيق في قضايا ابتزاز. ولم يتسنَّ حتى الآن التحقق بصورة مستقلة من صحة خبر الاعتقال أو من تفاصيل الاتهامات المنسوبة إلى المالكي، بانتظار صدور تأكيد رسمي من الجهات المختصة.'
    }

    data['items'] = [bilal, kirkuk] + items
    data['updated_at'] = datetime.now(timezone.utc).isoformat()
    NEWS.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')
    print('تم تثبيت الخبر العاجل وصورة بلال المالكي، مع الحفاظ على خبر كركوك التحريري')


if __name__ == '__main__':
    main()
